-- Real project data snapshot; import into an EMPTY database after schema.sql.
-- Contains no credentials and no DROP/DELETE/TRUNCATE statements.
SET @snapshot_sql_mode = @@SESSION.sql_mode;
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION';
SET NAMES utf8mb4;
SET time_zone = '+00:00';
START TRANSACTION;
COMMIT;
SET SESSION sql_mode = @snapshot_sql_mode;
